import { createRequire } from "node:module";
import { writeFileSync, mkdirSync } from "node:fs";
const CLONE = process.env.CLONE;
const OUT = process.env.OUT;
mkdirSync(OUT, { recursive: true });
const require = createRequire(CLONE + "/packages/web/package.json");
const { chromium } = require("@playwright/test");
const BASE = "http://127.0.0.1:5310";
const routes = ["/", "/docs", "/app/run", "/app/certificates", "__CERT__", "/app/approvals", "/app/business", "/app/incidents", "/app/chat", "/app/report", "/app/run?fixtures=1", "/app/incidents?fixtures=1"];
const browser = await chromium.launch({ channel: "chrome" });
const results = [];
let certHref = null;
for (const width of [1440, 390]) {
  const ctx = await browser.newContext({ viewport: { width, height: width === 390 ? 844 : 900 } });
  for (let r of routes) {
    if (r === "__CERT__") { if (!certHref) { results.push({ route: r, width, err: "no cert link" }); continue; } r = certHref; }
    const page = await ctx.newPage();
    const errors = [], consoleErr = [], bad = [];
    page.on("pageerror", (e) => errors.push(String(e.message).slice(0, 300)));
    page.on("console", (m) => { if (m.type() === "error") consoleErr.push(m.text().slice(0, 300)); });
    page.on("response", (res) => { if (res.status() >= 400) bad.push(res.status() + " " + res.url()); });
    try {
      await page.goto(BASE + r, { waitUntil: "networkidle", timeout: 30000 });
    } catch (e) { errors.push("goto: " + e.message.slice(0, 200)); }
    await page.waitForTimeout(2500);
    const info = await page.evaluate(() => {
      const de = document.documentElement;
      const wide = [];
      if (de.scrollWidth > de.clientWidth + 1) {
        for (const el of document.querySelectorAll("body *")) {
          const rc = el.getBoundingClientRect();
          if (rc.right > de.clientWidth + 1 && rc.width > 0 && getComputedStyle(el).position !== "fixed") {
            wide.push(el.tagName + "." + String(el.className).slice(0, 60) + " right=" + Math.round(rc.right));
            if (wide.length > 5) break;
          }
        }
      }
      return { scrollW: de.scrollWidth, clientW: de.clientWidth, text: document.body.innerText, wide };
    });
    if (!certHref && r === "/app/certificates") {
      certHref = await page.evaluate(() => { const a = [...document.querySelectorAll("a[href]")].map((a) => a.getAttribute("href")).find((h) => /^\/app\/certificates\/.+/.test(h)); return a || null; });
    }
    const words = [...info.text.matchAll(/[^\n]{0,60}\b(demo|simulated|fixtures?|sample)\b[^\n]{0,60}/gi)].map((m) => m[0].trim()).slice(0, 12);
    const loading = [...info.text.matchAll(/[^\n]{0,40}\b(loading|Loading)\b[^\n]{0,40}/g)].map((m) => m[0]).slice(0, 5);
    const slug = (r.replace(/[^a-z0-9]+/gi, "_") || "root") + "_" + width;
    writeFileSync(`${OUT}/${slug}.txt`, info.text);
    if (width === 1440 || r.includes("business") || r === "/") await page.screenshot({ path: `${OUT}/${slug}.png`, fullPage: false });
    results.push({ route: r, width, errors, consoleErr, bad, overflow: info.scrollW > info.clientW + 1 ? `${info.scrollW}>${info.clientW}` : null, wide: info.wide, words, loading, len: info.text.length });
    await page.close();
  }
  await ctx.close();
}
await browser.close();
writeFileSync(`${OUT}/results.json`, JSON.stringify(results, null, 1));
for (const x of results) {
  console.log(`${x.width} ${x.route} len=${x.len} err=${x.errors?.length ?? "-"} cons=${x.consoleErr?.length ?? "-"} bad=${x.bad?.length ?? "-"} overflow=${x.overflow} words=${x.words?.length ?? "-"} loading=${x.loading?.length ?? "-"} ${x.err ?? ""}`);
}

