await page.getByRole("button", { name: /^Instant$/ }).first().click().catch((e) => console.log("instant click failed", e.message));
await page.waitForTimeout(2000);
t = await page.evaluate(() => document.body.innerText);
writeFileSync(OUT + "/run_instant.txt", t);
