import { createRequire } from "node:module";
import { writeFileSync } from "node:fs";
const CLONE = process.env.CLONE, OUT = process.env.OUT;
const require = createRequire(CLONE + "/packages/web/package.json");
const { chromium } = require("@playwright/test");
const BASE = "http://127.0.0.1:5310";
const browser = await chromium.launch({ channel: "chrome" });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const errs = [];
const page = await ctx.newPage();
page.on("pageerror", (e) => errs.push("pageerror " + e.message));
page.on("console", (m) => { if (m.type() === "error") errs.push("console " + m.text()); });
page.on("response", (r) => { if (r.status() >= 400) errs.push(r.status() + " " + r.url()); });

// 1. Landing: scroll through, wait, check loading strings gone
await page.goto(BASE + "/", { waitUntil: "networkidle" });
for (let y = 0; y < 30; y++) { await page.mouse.wheel(0, 900); await page.waitForTimeout(250); }
await page.waitForTimeout(4000);
let t = await page.evaluate(() => document.body.innerText);
writeFileSync(OUT + "/landing_scrolled.txt", t);
console.log("landing loading strings after scroll:", [...t.matchAll(/[^\n]{0,40}Loading[^\n]{0,40}/g)].map((m) => m[0]));
console.log("landing overflow:", await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));

// 2. Run page instant
await page.goto(BASE + "/app/run", { waitUntil: "networkidle" });
await page.getByRole("button", { name: /^Instant$/ }).first().click().catch((e) => console.log("instant click failed", e.message));
await page.waitForTimeout(2000);
t = await page.evaluate(() => document.body.innerText);
writeFileSync(OUT + "/run_instant.txt", t);
const i = t.indexOf("Probes run");
console.log("run instant stats:", JSON.stringify(t.slice(i - 200, i + 300)));

// 3. Chat question
await page.goto(BASE + "/app/chat", { waitUntil: "networkidle" });
const box = page.getByRole("textbox").first();
await box.fill("What do we know about crustdata's enrich.headcount-total-integer?");
await box.press("Enter");
await page.waitForTimeout(12000);
t = await page.evaluate(() => document.body.innerText);
writeFileSync(OUT + "/chat_answer.txt", t);
await page.screenshot({ path: OUT + "/chat_answer.png", fullPage: true });
const links = await page.evaluate(() => [...document.querySelectorAll("main a[href]")].map((a) => a.getAttribute("href")).filter((h) => /certificates|run|bundle|#/.test(h)).slice(0, 15));
console.log("chat links:", links);
console.log("ERRORS:", errs);
await browser.close();

